get.description:
AK-28 · Gửi một lượt. Backend PROXY stream xuống Frontend —
Frontend không bao giờ giữ service token của Gateway.

Chống trùng CHỈ dựa vào Idempotency-Key, KHÔNG dựa clientMessageId
(contract mục 11.2 — đây là chỗ v0.1 để mơ hồ).
/
export const POST = handler(async (req: Request, ctx: Ctx) => {
  const user = requireUser(req);
  const { id } = await ctx.params;
  const s = await getOwnedSession(id, user.id);
  if (!s.aiSession?.gatewaySessionId) throw NotFound('Phiên chưa được tạo trên Gateway');

  const body = schema.parse(await req.json());
  const api = gateway();
  const key = `turn-${s.id}-${body.clientMessageId}`;
  const payload = { client_message_id: body.clientMessageId, text: body.text };

  const wantsStream = req.headers.get('accept')?.includes('text/event-stream');

  if (!wantsStream) {
    const turn = await api.sendMessage(s.aiSession.gatewaySessionId, payload, key);
    await saveTurn(s.id, body, turn as Record<string, unknown>);
    return Response.json({ data: turn });
  }

  const upstream = await api.streamMessage(s.aiSession.gatewaySessionId, payload, key);
  if (!upstream.ok || !upstream.body) {
    const err = await upstream.json().catch(() => ({}));
    return Response.json(err, { status: upstream.status });
  }

Tách stream: một nhánh chảy thẳng xuống FE, một nhánh để lưu lượt vào DB.
Nhánh lưu hỏng KHÔNG được làm hỏng nhánh người dùng đang xem.
  const toClient = teeAndParse(upstream.body, async (ev) => {
    if (ev.event === 'turn.completed') {
      await saveTurn(s.id, body, ev.data as Record<string, unknown>).catch(() => {});
    }
  });

  return new Response(toClient, { headers: SSE_HEADERS });
});

async function saveTurn(sessionId: string, body: { clientMessageId: string; text: string }, t: Record<string, unknown>) {
  const turnIndex = Number(t.turn_index ?? 0);
  if (!turnIndex) return;
  await prisma.roleplayTurn.upsert({
UNIQUE(session, turnIndex) — SSE có thể lặp khi retry, upsert để không nhân đôi
    where: { practiceSessionId_turnIndex: { practiceSessionId: sessionId, turnIndex } },
    create: {
      practiceSessionId: sessionId, gatewayTurnId: String(t.turn_id ?? ''), turnIndex,
      clientMessageId: body.clientMessageId, learnerText: body.text,
      personaText: String(t.persona_text ?? ''), emotionState: t.emotion_state as string,
      escalationLevel: t.escalation_level as number, finishReason: t.finish_reason as string,
      inputTokens: (t.usage as { input_tokens?: number })?.input_tokens,
      outputTokens: (t.usage as { output_tokens?: number })?.output_tokens,
    },
    update: {},
  });
  await prisma.aiRoleplaySession.updateMany({
    where: { practiceSessionId: sessionId }, data: { turnsUsed: turnIndex, status: 'ACTIVE' },
  });
}

